import type { TableModel } from './tableModel'

const FONT = 'ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace'
const PAD_X = 10
const ROW_H = 28
const MARGIN = 16
const TITLE_H = 34
export const MAX_CANVAS_SIDE = 16000
// iOS Safari refuses canvases above 16 777 216 px (4096²); keep some margin.
export const MAX_CANVAS_AREA = 16_000_000

/** Bitmap pixels per CSS pixel: 2× for sharpness, less when the canvas would exceed a side or the area limit. */
export function canvasScale(w: number, h: number) {
  const s = Math.min(2, MAX_CANVAS_SIDE / w, MAX_CANVAS_SIDE / h, Math.sqrt(MAX_CANVAS_AREA / (w * h)))
  return Math.floor(s * 1000) / 1000
}

export async function tableToPng(t: TableModel): Promise<{ blob: Blob; width: number }> {
  const measure = document.createElement('canvas').getContext('2d')!
  const width = (text: string, bold: boolean) => {
    measure.font = `${bold ? 'bold ' : ''}14px ${FONT}`
    return measure.measureText(text).width
  }
  // Row 0 is the header; column 0 holds the row headers.
  type Cell = { text: string; head: boolean; conflict: boolean }
  const all: Cell[][] = [
    t.header.map((text) => ({ text, head: true, conflict: false })),
    ...t.rows.map((r) => [{ text: r.head, head: true, conflict: false }, ...r.cells.map((c) => ({ text: c.text, head: false, conflict: c.conflict }))]),
  ]
  const cols = t.header.map((_, c) => Math.ceil(Math.max(28, ...all.map((r) => width(r[c]?.text ?? '', Boolean(r[c]?.head || r[c]?.conflict)))) + PAD_X * 2))
  const tableW = cols.reduce((s, w) => s + w, 0)
  const w = Math.max(tableW, width(t.title, true) + 4) + MARGIN * 2
  const h = TITLE_H + ROW_H * all.length + MARGIN * 2
  const scale = canvasScale(w, h)

  const canvas = document.createElement('canvas')
  canvas.width = Math.max(1, Math.floor(w * scale))
  canvas.height = Math.max(1, Math.floor(h * scale))
  const ctx = canvas.getContext('2d')!
  ctx.scale(scale, scale)
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, w, h)

  ctx.fillStyle = '#18181b'
  ctx.font = `bold 16px ${FONT}`
  ctx.textBaseline = 'middle'
  ctx.fillText(t.title, MARGIN, MARGIN + TITLE_H / 2 - 4)

  const top = MARGIN + TITLE_H
  all.forEach((row, r) => {
    let x = MARGIN
    const y = top + r * ROW_H
    cols.forEach((cw, c) => {
      const { text, head, conflict } = row[c] ?? { text: '', head: false, conflict: false }
      if (head || conflict) {
        ctx.fillStyle = conflict ? '#fee2e2' : '#f4f4f5'
        ctx.fillRect(x, y, cw, ROW_H)
      }
      ctx.font = `${head || conflict ? 'bold ' : ''}14px ${FONT}`
      ctx.fillStyle = conflict ? '#b91c1c' : head ? '#18181b' : '#3730a3'
      ctx.textAlign = c === 0 ? 'left' : 'center'
      ctx.fillText(text, c === 0 ? x + PAD_X : x + cw / 2, y + ROW_H / 2 + 1)
      x += cw
    })
  })

  ctx.strokeStyle = '#d4d4d8'
  ctx.lineWidth = 1
  ctx.beginPath()
  for (let r = 0; r <= all.length; r++) {
    ctx.moveTo(MARGIN, top + r * ROW_H + 0.5)
    ctx.lineTo(MARGIN + tableW, top + r * ROW_H + 0.5)
  }
  let x = MARGIN
  for (let c = 0; c <= cols.length; c++) {
    ctx.moveTo(x + 0.5, top)
    ctx.lineTo(x + 0.5, top + all.length * ROW_H)
    x += cols[c] ?? 0
  }
  ctx.stroke()

  return new Promise((resolve, reject) => canvas.toBlob((b) => (b ? resolve({ blob: b, width: w }) : reject(new Error('PNG sa nepodarilo vytvoriť'))), 'image/png'))
}
